"""Simulated mice for the strategy-comparison tests: each generated by one of the three models."""

import numpy as np
import pandas as pd

from src.agents import drifting_simulation as sim
from src.agents import heuristic_agent as ha
from src.agents import null_agents as na
from src.behavior_analysis import strategy_models as sm
from src.behavior_analysis.drifting_trial_table import drifting_trial_table
from src.pipelines.choice_logit_values import SIMULATED_PORTS, START_MAGNITUDES

RULES = sim.TaskRules(drift_rate=0.1, block_lengths=np.arange(30, 36))
WSLS = na.WslsMagnitudeParams(a_win=0.4, a_lose=-0.3, b=0.2, w=0.7)
HEURISTIC = ha.HeuristicPlusParams(a_win=0.4, a_lose=-0.3, b=0.2, w=0.7, v=1.2, u=1.0)
Q_LEARNER = (0.25, 2.5, 0.8, 0.3)  # learning rate, beta, kappa, plus bias
PARAMETERS = {sm.WSLS_MAGNITUDE: WSLS, sm.HEURISTIC_PLUS: HEURISTIC, sm.Q_LEARNER: Q_LEARNER}


def layouts(n_problems: int, sessions: int, trials: int, seed: int) -> dict:
    """``{problem: MouseLayout}``: other towers in each problem, random start magnitudes."""
    rng = np.random.default_rng(seed)
    out = {}
    for k in range(n_problems):
        ports = sorted(SIMULATED_PORTS[k % len(SIMULATED_PORTS)])
        magnitudes = dict(zip(ports, (int(m) for m in rng.permutation(START_MAGNITUDES)),
                              strict=True))  # fmt: skip
        out[k + 1] = sim.MouseLayout(ports, "B2", magnitudes, [trials] * sessions)
    return out


def simulate_mouse(
    model: str,
    params=None,
    seed: int = 0,
    mouse: str = "m",
    n_problems: int = 4,
    sessions: int = 2,
    trials: int = 250,
) -> pd.DataFrame:
    """One mouse's trial table, played by *model* (default parameters of ``PARAMETERS``)."""
    params = PARAMETERS[model] if params is None else params
    played = sim.simulate_policy_mouse(
        lambda layout: sm.SPECS[model].policy(params, layout),
        layouts(n_problems, sessions, trials, seed),
        RULES,
        np.random.default_rng([seed, 1]),
        mouse,
    )
    return drifting_trial_table(played)
